/* @lc app=leetcode id=3225 lang=kotlin */
class Solution { fun maximumScore(grid: Array<IntArray>): Long = grid.size.let { n -> Array(n + 1) { r -> LongArray(n) { c -> (0 until r).sumOf { grid[it][c].toLong() } } }.let { pref -> Array(n + 1) { Array(n + 1) { LongArray(n + 1) { -1L } } }.let { dp -> DeepRecursiveFunction<Triple<Int, Int, Int>, Long> { (col, prev, cur) -> if (col >= n) 0L else if (dp[col][prev][cur] != -1L) dp[col][prev][cur] else maxOf(pref[cur][col] + callRecursive(Triple(col + 1, 0, prev)), if (col + 1 < n) (prev until n).maxOfOrNull { i -> pref[i + 1][col] - pref[prev][col] + callRecursive(Triple(col + 1, i + 1, 0)) } ?: 0L else 0L, (0 until n).maxOfOrNull { i -> maxOf(0L, pref[cur][col] - pref[i + 1][col]) + callRecursive(Triple(col + 1, 0, i + 1)) } ?: 0L).also { dp[col][prev][cur] = it } }.invoke(Triple(0, 0, 0)) } } }